function FlagIcon({code,className=''}:{code:string;className?:string}){const file=code==='OTHER'?'other.svg':`${code.toLowerCase()}.svg`;return <span className={`nationalFlag ${className}`} title={countryMeta(code).name}><img src={`/flags/${file}`} alt={`${countryMeta(code).name} flag`}/></span>}
function LeagueMark({region,showName=false}:{region:Region;showName?:boolean}){return <span className={`leagueMark leagueMark${region}`}><i><img src={REGIONS[region].logo} alt={`${REGIONS[region].name} logo`}/></i>{showName&&<b>{REGIONS[region].name}</b>}</span>}

